//! Host app metadata, state paths, and app-level lifecycle helpers.
//!
//! These APIs describe the native host application, not an individual LxApp
//! page. They are intended for Rust native code built with LingXia, including
//! code generated by `lingxia::native`.
//!
//! Common uses:
//!
//! - read product metadata such as `product_version` and `lingxia_id`;
//! - resolve host-owned state paths such as `state_dir` and `state_file`;
//! - read or set the host display language (`display_language`,
//!   `set_display_language_preference`);
//! - request host app termination with `exit`.

use std::path::{Component, Path, PathBuf};
use std::sync::OnceLock;

use lingxia_platform::traits::app_runtime::AppRuntime;

pub use lingxia_app_context::AppEnv;
pub use lxapp::{
    DisplayLanguageEffectiveSource, DisplayLanguagePreference, DisplayLanguageState, LanguageTag,
};

static APP_DATA_DIR: OnceLock<PathBuf> = OnceLock::new();

pub(crate) fn set_data_dir(path: PathBuf) {
    let _ = APP_DATA_DIR.set(path);
}

/// Returns the host app's display name from the initialized app config.
pub fn product_name() -> Option<&'static str> {
    lingxia_app_context::product_name()
}

/// Returns the host app version from the initialized app config.
pub fn product_version() -> Option<&'static str> {
    lingxia_app_context::product_version()
}

/// Returns the host deployment environment baked into the running product.
pub fn env() -> AppEnv {
    lingxia_app_context::env()
}

/// Returns the configured home LxApp id from the initialized app config.
pub fn home_app_id() -> Option<&'static str> {
    lingxia_app_context::home_app_id()
}

#[cfg(any(target_os = "ios", target_os = "macos", target_os = "windows"))]
pub(crate) fn launch_home_control_logic() -> crate::Result<()> {
    let app_id =
        home_app_id().ok_or_else(|| crate::Error::internal("home lxapp is not configured"))?;
    let app = lxapp::try_get(app_id)
        .ok_or_else(|| crate::Error::internal(format!("home lxapp '{app_id}' is not ready")))?;
    app.ensure_app_service_running()
        .map_err(|error| crate::Error::internal(error.to_string()))?;
    app.ensure_app_launch_dispatched()
        .map_err(|error| crate::Error::internal(error.to_string()))
}

/// Returns the configured LingXia host identifier, if any.
pub fn lingxia_id() -> Option<&'static str> {
    lingxia_app_context::lingxia_id()
}

/// Reports whether push-notification capability is enabled for the host app.
pub fn notifications_enabled() -> bool {
    lingxia_app_context::notifications_enabled()
}

/// Returns the effective host display language.
///
/// A pinned [`DisplayLanguagePreference::LanguageTag`] takes precedence over
/// the native host locale. [`DisplayLanguagePreference::Auto`] follows it.
pub fn display_language() -> String {
    lxapp::display_language()
}

/// Follow the effective language. Runs only when the tag actually changes.
pub fn watch_display_language(listener: impl Fn(LanguageTag) + Send + Sync + 'static) {
    lxapp::add_display_language_effective_listener(Box::new(listener));
}

/// What the user chose: `Auto`, or a pinned tag.
pub fn display_language_preference() -> DisplayLanguagePreference {
    lxapp::display_language_state().preference
}

/// Persist the product's display language and publish it after the write succeeds.
pub fn set_display_language_preference(preference: DisplayLanguagePreference) -> crate::Result<()> {
    lxapp::set_display_language_preference_in(&data_dir()?, preference).map_err(Into::into)
}

/// Follow the choice, not what it resolves to: a system locale change under
/// `Auto` moves the effective tag without moving the preference.
pub fn watch_display_language_preference(
    listener: impl Fn(DisplayLanguagePreference) + Send + Sync + 'static,
) {
    let last = std::sync::Mutex::new(None::<DisplayLanguagePreference>);
    lxapp::add_display_language_state_listener(Box::new(move |state: DisplayLanguageState| {
        let mut last = last.lock().unwrap_or_else(|error| error.into_inner());
        if last.as_ref() == Some(&state.preference) {
            return;
        }
        *last = Some(state.preference.clone());
        drop(last);
        listener(state.preference);
    }));
}

pub(crate) fn data_dir() -> crate::Result<PathBuf> {
    APP_DATA_DIR
        .get()
        .cloned()
        .ok_or_else(|| crate::Error::internal("app data directory is not initialized"))
}

/// Returns the host-owned state directory.
pub fn state_dir() -> crate::Result<PathBuf> {
    Ok(lingxia_app_context::app_state_dir(&data_dir()?))
}

/// Returns the full path to a file inside the host-owned state directory.
pub fn state_file(name: &str) -> crate::Result<PathBuf> {
    state_file_in(data_dir()?, name)
}

/// Returns the state directory for a specific running [`crate::LxApp`].
pub fn state_dir_for(app: &crate::LxApp) -> PathBuf {
    lingxia_app_context::app_state_dir(&app.user_data_dir)
}

/// Returns a file path inside an [`crate::LxApp`]'s state directory.
pub fn state_file_for(app: &crate::LxApp, name: &str) -> crate::Result<PathBuf> {
    state_file_in(&app.user_data_dir, name)
}

/// OS local notifications, for native hosts that have no JS Logic.
///
/// The same contract `lx.host.notification` exposes: `id` is the replace key,
/// and a tap resolves through [`crate::navigation`], so a native host can send
/// the user to a native screen without inventing a product URL for it.
pub mod notification {
    pub use lingxia_platform::traits::app_runtime::LocalNotificationStatus;
    use lingxia_platform::traits::app_runtime::{AppRuntime, LocalNotificationShow};
    use lingxia_service::navigation::{self, NavigationTarget, intent};

    /// One notification to post or replace.
    pub struct Notification {
        id: String,
        title: String,
        body: String,
        target: NavigationTarget,
        deliver_at_ms: Option<u64>,
        silent: bool,
    }

    impl Notification {
        /// `id` is the replace key: anything pending or delivered under it is
        /// replaced, and its old target stops resolving.
        pub fn new(id: impl Into<String>, title: impl Into<String>) -> Self {
            Self {
                id: id.into(),
                title: title.into(),
                body: String::new(),
                target: NavigationTarget::Activate,
                deliver_at_ms: None,
                silent: false,
            }
        }

        pub fn body(mut self, body: impl Into<String>) -> Self {
            self.body = body.into();
            self
        }

        /// Where the tap goes. Without one the product simply comes forward.
        pub fn target(mut self, target: NavigationTarget) -> Self {
            self.target = target;
            self
        }

        /// Epoch milliseconds. A time that is not in the future means now.
        pub fn deliver_at_ms(mut self, at_ms: u64) -> Self {
            self.deliver_at_ms = Some(at_ms);
            self
        }

        pub fn silent(mut self, silent: bool) -> Self {
            self.silent = silent;
            self
        }
    }

    /// The same capability gate the JS API answers to: a host that did not
    /// declare `capabilities.notifications` has no notification API at all,
    /// in Rust or in Logic.
    fn require_capability() -> crate::Result<()> {
        if lingxia_app_context::capability::notifications() {
            return Ok(());
        }
        Err(crate::Error::invalid_request(
            "this host did not declare capabilities.notifications",
        ))
    }

    /// `"granted"`, `"denied"`, or `"default"`. Never prompts.
    pub fn permission() -> crate::Result<String> {
        require_capability()?;
        crate::runtime::platform()?
            .notification_permission()
            .map_err(crate::Error::from)
    }

    /// Prompts where the OS has a prompt; otherwise reports the setting.
    pub fn request_permission() -> crate::Result<String> {
        require_capability()?;
        crate::runtime::platform()?
            .notification_request_permission()
            .map_err(crate::Error::from)
    }

    /// Post or replace. The target is validated before anything is persisted
    /// or handed to the OS, so an unknown route fails here rather than on tap.
    pub fn show(request: Notification) -> crate::Result<LocalNotificationStatus> {
        require_capability()?;
        if request.id.trim().is_empty() {
            return Err(crate::Error::invalid_request("notification id is empty"));
        }
        if request.title.trim().is_empty() {
            return Err(crate::Error::invalid_request("notification title is empty"));
        }
        navigation::validate(&request.target)
            .map_err(|error| crate::Error::invalid_request(error.to_string()))?;
        let platform = crate::runtime::platform()?;
        let staged = intent::stage(&request.id, &request.target)
            .map_err(|error| crate::Error::internal(error.to_string()))?;
        let outcome = platform.notification_show(&LocalNotificationShow {
            id: request.id,
            title: request.title,
            body: request.body,
            activation_token: staged.token.clone(),
            deliver_at_ms: request.deliver_at_ms,
            silent: request.silent,
        });
        match outcome {
            // Suppressed posts nothing, so nothing may resolve this token.
            Ok(LocalNotificationStatus::Suppressed) => {
                intent::rollback(&staged);
                Ok(LocalNotificationStatus::Suppressed)
            }
            Ok(status) => {
                intent::commit(&staged);
                Ok(status)
            }
            Err(error) => {
                intent::rollback(&staged);
                Err(crate::Error::from(error))
            }
        }
    }

    /// Remove what is pending or delivered under `id`, and retire its target.
    pub fn cancel(id: &str) -> crate::Result<()> {
        require_capability()?;
        intent::invalidate(id);
        crate::runtime::platform()?
            .notification_cancel(id)
            .map_err(crate::Error::from)
    }

    pub fn cancel_all() -> crate::Result<()> {
        require_capability()?;
        intent::invalidate_all();
        crate::runtime::platform()?
            .notification_cancel_all()
            .map_err(crate::Error::from)
    }
}

/// Product-drawn desktop banner (top-right). Not an OS notification.
pub mod banner {
    use lingxia_platform::traits::app_runtime::AppRuntime;
    pub use lingxia_platform::traits::app_runtime::{
        DesktopBannerAction, DesktopBannerActionStyle, DesktopBannerBackground,
        DesktopBannerOutcome, DesktopBannerShow,
    };

    /// Present a banner and wait until it is answered, dismissed, timed out, or replaced.
    pub fn show(request: DesktopBannerShow) -> crate::Result<DesktopBannerOutcome> {
        crate::runtime::platform()?
            .banner_show(&request)
            .map_err(crate::Error::from)
    }

    /// Dismiss a visible or queued banner. Unknown ids are fine.
    pub fn dismiss(id: &str) -> crate::Result<()> {
        crate::runtime::platform()?
            .banner_dismiss(id)
            .map_err(crate::Error::from)
    }
}

/// Show or hide the desktop shell's "an AI assistant is in control" indicator.
///
/// `lingxia-control-runtime` drives this from its session events; a product
/// does not need to call it.
#[doc(hidden)]
pub fn set_control_session_indicator(active: bool) -> crate::Result<()> {
    crate::runtime::platform()?
        .set_control_session_indicator(active)
        .map_err(crate::Error::from)
}

/// What the indicator's Stop button does. Installed by the control runtime.
#[doc(hidden)]
pub fn set_control_session_stop_handler(handler: impl Fn() + Send + Sync + 'static) {
    lingxia_platform::set_control_session_stop_handler(std::sync::Arc::new(handler));
}

/// Requests host app termination through the active platform runtime.
pub fn exit() -> crate::Result<()> {
    crate::bootstrap::teardown_runner_display_language_session();
    crate::runtime::platform()?
        .exit()
        .map_err(crate::Error::from)?;
    Ok(())
}

fn state_file_in(root: impl AsRef<Path>, name: &str) -> crate::Result<PathBuf> {
    validate_state_file_name(name)?;
    Ok(lingxia_app_context::app_state_file(root.as_ref(), name))
}

fn validate_state_file_name(name: &str) -> crate::Result<()> {
    let path = Path::new(name);
    if name.trim().is_empty() {
        return Err(crate::Error::invalid_request("state file name is empty"));
    }
    if path
        .components()
        .any(|component| !matches!(component, Component::Normal(_) | Component::CurDir))
    {
        return Err(crate::Error::invalid_request(
            "state file name must be relative and stay inside the state directory",
        ));
    }
    Ok(())
}
